<script setup>
import { computed, ref } from 'vue';
import CircuitScene from './components/CircuitScene.vue';
import ComponentLibrary from './components/ComponentLibrary.vue';
import { lessons } from './data/lessons';
const tab = ref('ohm'); const circuit = ref('led'); const running = ref(true); const selected = ref(null); const placed = ref(['battery', 'resistor', 'led']);
const lesson = computed(() => lessons[tab.value]);
const readings = computed(() => circuit.value === 'divider' ? ['4.0 V', '40.0 mA', 'VOUT'] : circuit.value === 'inverter' ? ['5.0 V', '2.1 mA', 'OUT: 0'] : ['9.0 V', '18.0 mA', 'LED ON']);
function addComponent(component) { placed.value.push(component.id); selected.value = component; }
</script>
<template><main class="app-shell"><header class="topbar"><div class="brand"><div class="brand-mark">⌁</div><div><span class="eyebrow">Electronics playground</span><h1>CircuitForge Lab</h1><p>Aprende construyendo, midiendo y preguntando.</p></div></div><button class="button primary" @click="running = !running">{{ running ? 'Ⅱ Pausar' : '▶ Ejecutar simulación' }}</button></header><section class="hero-grid"><article class="card intro"><span class="eyebrow">Laboratorio 01 · desde cero</span><h2>La electrónica se entiende cuando la puedes tocar.</h2><p>Explora una mesa 3D, observa cómo circula la corriente y practica con ejemplos seguros.</p><span class="pill">Niños curiosos</span><span class="pill">Adultos principiantes</span><span class="pill">Sin soldar</span></article><section class="card scene-wrap"><CircuitScene/></section></section><section class="editor card"><ComponentLibrary :selected-id="selected?.id" @select="selected = $event" @add="addComponent"/><section class="editor-stage"><div class="stage-toolbar"><div><span class="eyebrow">Editor interactivo</span><h2>Banco de trabajo</h2></div><span class="stage-status">{{ placed.length }} componentes · {{ running ? 'simulando' : 'pausado' }}</span></div><div class="stage-board"><CircuitScene/><div class="placed-components"><button v-for="(id, index) in placed" :key="`${id}-${index}`" class="placed-chip" @click="selected = { id }">{{ id.toUpperCase() }} <small>#{{ index + 1 }}</small></button></div></div></section><aside class="inspector"><span class="eyebrow">Inspector</span><h3>{{ selected?.name || 'Selecciona un componente' }}</h3><p>{{ selected?.description || 'Elige un elemento de la biblioteca para consultar sus pines y propiedades.' }}</p><dl v-if="selected"><div><dt>Valor</dt><dd>{{ selected.value }}</dd></div><div><dt>Pines</dt><dd>{{ selected.pins.join(' · ') }}</dd></div><div><dt>Modelo</dt><dd>3D realista · GLB</dd></div></dl><button v-if="selected" class="button" @click="selected = null">Deseleccionar</button></aside></section><section class="work-grid"><section class="card"><div class="panel-head"><h2>Práctica activa</h2><span>{{ running ? 'CIRCUITO ACTIVO' : 'PAUSADO' }}</span></div><div class="pad"><div class="circuit-grid"><button v-for="item in [['led','LED + resistencia'],['divider','Divisor de voltaje'],['inverter','Inversor NOT']]" :key="item[0]" class="circuit-button" :class="{selected:circuit===item[0]}" @click="circuit=item[0]"><strong>{{ item[1] }}</strong></button></div><div class="readings"><div v-for="(reading,index) in readings" :key="reading"><b>{{ reading }}</b><small>{{ ['Fuente DC','Corriente','Salida'][index] }}</small></div></div></div></section><aside class="card lesson"><h3>Ruta de aprendizaje</h3><p>Identifica la fuente, el camino y la carga; predice el resultado y compáralo con la medición.</p><ol><li>Observa el circuito.</li><li>Elige una práctica.</li><li>Explica el porqué.</li></ol></aside></section><section class="card education"><nav class="tabs"><button v-for="(_, key) in lessons" :key="key" class="button" :class="{active:tab===key}" @click="tab=key">{{ lessons[key].title }}</button></nav><div class="content"><h2>{{ lesson.title }}</h2><p>{{ lesson.subtitle }}</p><div class="formula">{{ lesson.formula }}</div><div class="learn-grid"><article v-for="card in lesson.cards" :key="card.title"><h3>{{ card.title }}</h3><p>{{ card.body }}</p><code v-if="card.code">{{ card.code }}</code></article></div></div></section><footer>Construido con Vue, Vite y Three.js · <a href="https://github.com/uppy19d0/circuitforge-lab" target="_blank">Repositorio en GitHub</a></footer></main></template>
